import openmc

# Load the statepoint file generated by the simulation
sp = openmc.StatePoint('statepoint.50.h5')

# Retrieve the blanket performance tally
tally = sp.get_tally(name='blanket_performance')

print("\n" + "="*40)
print("     FUSION BLANKET PERFORMANCE RESULTS     ")
print("="*40)
df = tally.get_pandas_dataframe()
print(df[['score', 'mean', 'std. dev.']])
print("="*40 + "\n")
